INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published)
VALUES ('2006-12-05-hong-kong-the-consumption-tax-that-was-not', '2006-12-05', '2006-12', 'The Government withdrew a goods and services tax from its tax-base consultation five months after proposing it. Two decades on, that decision is still the reason Hong Kong has no e-invoicing rule of any kind.', '<h3>🇭🇰 Hong Kong drops the tax that every e-invoicing mandate exists to protect</h3><p>In July 2006 the Government opened a consultation titled <em>Broadening the Tax Base, Ensuring Our Future Prosperity</em>, proposing a low, single-rate goods and services tax. In December it withdrew the proposal. The interim report recorded that <q>at this point in time there is insufficient public support nor are the conditions right for the introduction of GST</q>, and the final report of June 2007 closed the exercise.</p><p>It reads as a domestic tax story, and for twenty years that is all it was. It matters here because of what follows from it. Every mandate this site tracks — Italy''s clearance, Poland''s KSeF, Mexico''s CFDI, the whole of ViDA — exists to protect a value-added tax. The invoice is standardised because the tax authority needs to see it. Hong Kong has no value-added tax, no goods and services tax and no sales tax, so its law contains no such thing as a tax invoice, and there is nothing for a mandate to standardise.</p><p>The practical consequence is unusual enough to be worth stating plainly: in Hong Kong an invoice is an ordinary commercial document. No statute prescribes what it must contain, no authority sees it, no format is imposed, and no signature is required. What the law does require is that you keep it — seven years of sufficient records under the Inland Revenue Ordinance, with a fine of up to HK$100,000 for failing to.</p><p>Note the wording the Government chose in 2006. Not that a consumption tax was wrong, but that there was insufficient support <em>at this point in time</em>. It was shelved rather than buried, and the day it is taken off the shelf is the day everything on this page changes.</p>', 'https://www.info.gov.hk/gia/general/200612/05/P200612050102.htm', 1);
